window.SCHOOL_LISTENING={"../assets/media/ba137d8e003fb543d6d94368f4b284cd762ea3bacb3dfc117c802224534ece67.mp3":[{"id":"PPT_ba137d8e003fb543","audioId":"PPT_ba137d8e003fb543","title":"Book 2 · Unit 6 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 102","duration":79.8,"cues":[{"start":0,"end":1.94,"text":"six .four","coverage":1},{"start":3.02,"end":3.41,"text":"Hi","coverage":1},{"start":3.41,"end":4.42,"text":"Sam,","coverage":1},{"start":4.82,"end":6.14,"text":"good to see you again.","coverage":1},{"start":6.4,"end":6.48,"text":"Hello","coverage":1},{"start":6.48,"end":6.96,"text":"Joe.","coverage":1},{"start":8.14,"end":8.4,"text":"So,","coverage":1},{"start":9.08,"end":13.4,"text":"last time we met we talked about your business goals.","coverage":1},{"start":14.04,"end":15.04,"text":"Was it useful?","coverage":1},{"start":15.72,"end":16.5,"text":"Useful?","coverage":1},{"start":16.92,"end":18.12,"text":"Yeah, it was.","coverage":1},{"start":18.86,"end":20.74,"text":"You really made me think.","coverage":1},{"start":21.32,"end":25.26,"text":"But now I have a lot of stress about losing money.","coverage":1},{"start":25.96,"end":26.62,"text":"Oh, yes.","coverage":1},{"start":27.18,"end":29.44,"text":"What is making you stressed about that?","coverage":1},{"start":29.44,"end":34.4,"text":"Well, I realized how many weaknesses a business can have.","coverage":1},{"start":35.06,"end":38.9,"text":"One careless mistake and I could lose a lot of money.","coverage":1},{"start":39.78,"end":40.22,"text":"Exactly.","coverage":1},{"start":41.22,"end":44.78,"text":"But there are things you think will cause you to lose money?","coverage":1},{"start":45.54,"end":49.74,"text":"Well, when we looked at the company's strengths and weaknesses,","coverage":1},{"start":50.36,"end":54.22,"text":"we talked about the quality and happiness of my workers,","coverage":1},{"start":54.8,"end":60.8,"text":"the costs of running the business and reaching new customers to help grow the business.","coverage":1},{"start":61.78,"end":70.06,"text":"Each of these areas could be a way to help make money or a way to lose money if you don't have a good plan.","coverage":1},{"start":70.84,"end":71.34,"text":"Wow,","coverage":1},{"start":71.7,"end":72.48,"text":"that's great.","coverage":1},{"start":73.1,"end":75.54,"text":"Those are all important to think about.","coverage":1},{"start":76.56,"end":77.9,"text":"Is there anything else?","coverage":1}],"file":"0c6127183027529468f5.js","track":0,"media":"../assets/media/ba137d8e003fb543d6d94368f4b284cd762ea3bacb3dfc117c802224534ece67.mp3"}],"../assets/media/bbb37b93b139cebfff3986e9fa4417b076a094a0cf930685781b9d582408c564.mp3":[{"id":"PPT_bbb37b93b139cebf","audioId":"PPT_bbb37b93b139cebf","title":"Book 2 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 58","duration":178.73,"cues":[{"start":0,"end":2,"text":"six .three","coverage":1},{"start":3.26,"end":4.44,"text":"Okay, Alika.","coverage":1},{"start":5.02,"end":6.56,"text":"Should we look at your project now?","coverage":1},{"start":7.28,"end":8.46,"text":"Yes, okay.","coverage":1},{"start":9.46,"end":12.58,"text":"You've done a lot of reading for this, which is great.","coverage":1},{"start":13.14,"end":15.96,"text":"I can see you wrote a lot of information down.","coverage":1},{"start":16.86,"end":19.5,"text":"Yes, but I haven't finished yet.","coverage":1},{"start":19.7,"end":24.78,"text":"I ran out of time, but I read as much as I could about","coverage":1},{"start":25.42,"end":27.38,"text":"103 different reports.","coverage":1},{"start":27.96,"end":32.52,"text":"I took part in the discussions on this with students from my study group.","coverage":1},{"start":33,"end":35.32,"text":"I studied the way people work.","coverage":1},{"start":36.26,"end":36.64,"text":"Good.","coverage":1},{"start":37.28,"end":38.76,"text":"Can you tell me what you learned?","coverage":1},{"start":39.84,"end":40.36,"text":"Well,","coverage":1},{"start":40.72,"end":44.02,"text":"I looked at how people spend time at work.","coverage":1},{"start":44.34,"end":50.42,"text":"I was interested in how people wasted time and why they didn't work hard at their jobs.","coverage":1},{"start":51.02,"end":55.66,"text":"I mean the reasons why they didn't focus on their work.","coverage":1},{"start":56.38,"end":59.2,"text":"I found out a lot of interesting information.","coverage":1},{"start":60.28,"end":61.14,"text":"For example,","coverage":1},{"start":61.78,"end":65.58,"text":"almost half of the workers wasted time on the internet.","coverage":1},{"start":66.2,"end":70.2,"text":"They were surfing the internet or writing personal emails.","coverage":1},{"start":70.88,"end":74.5,"text":"It was 48 % of workers, in fact.","coverage":1},{"start":75.34,"end":76.96,"text":"31 .five","coverage":1},{"start":76.96,"end":82.04,"text":"% also said they spent time talking to colleagues instead of working.","coverage":1},{"start":82.94,"end":85.14,"text":"And a little under half that amount,","coverage":1},{"start":86.1,"end":90.58,"text":"15%, said they took longer coffee and lunch breaks than they should.","coverage":1},{"start":91.4,"end":98.06,"text":"Only five % said they spent time texting friends and making plans for after work.","coverage":1},{"start":98.88,"end":99.44,"text":"Good.","coverage":1},{"start":100.24,"end":102.56,"text":"And did you find out the reasons why?","coverage":1},{"start":103.08,"end":103.76,"text":"Yes.","coverage":1},{"start":104.72,"end":110.02,"text":"Approximately half said they didn't work hard because they weren't happy in their jobs.","coverage":1},{"start":111.02,"end":111.78,"text":"I see.","coverage":1},{"start":112.6,"end":114.2,"text":"And about a third,","coverage":1},{"start":114.54,"end":116.92,"text":"33 .five%,","coverage":1},{"start":116.92,"end":119.72,"text":"thought they didn't earn a good enough salary.","coverage":1},{"start":120.4,"end":125.42,"text":"They said they didn't have enough money for holidays or nice clothes.","coverage":1},{"start":126.06,"end":128.94,"text":"They had just enough money to get by,","coverage":1},{"start":129.32,"end":132.2,"text":"so they didn't work as hard as they could.","coverage":1},{"start":132.56,"end":139.26,"text":"Some people, about 19%, said they had to work too many hours.","coverage":1},{"start":139.9,"end":143.92,"text":"So what are some effects of people not working very hard?","coverage":1},{"start":144.72,"end":145.4,"text":"Hmm.","coverage":1},{"start":146.06,"end":148.88,"text":"If people aren't working hard,","coverage":1},{"start":149.28,"end":151.98,"text":"companies don't get what they are paying for.","coverage":1},{"start":152.92,"end":154.36,"text":"Can you give me some examples?","coverage":1},{"start":155.46,"end":158.24,"text":"Well, when people don't work hard,","coverage":1},{"start":158.8,"end":160.54,"text":"productivity goes down.","coverage":1},{"start":160.94,"end":167.38,"text":"Because productivity depends on how fast workers make things or provide services,","coverage":1},{"start":168.08,"end":170.32,"text":"if workers are not working hard,","coverage":1},{"start":170.82,"end":172.86,"text":"the company doesn't make a profit.","coverage":1},{"start":173.6,"end":176.74,"text":"Then they can't pay higher salaries.","coverage":1}],"file":"1030ce1d156812df2b7e.js","track":0,"media":"../assets/media/bbb37b93b139cebfff3986e9fa4417b076a094a0cf930685781b9d582408c564.mp3"}],"../assets/media/10b01c336ee5d00db87c0179556888bf72d8b76d6ab9913a27ed2e277576ff12.mp3":[{"id":"PPT_10b01c336ee5d00d","audioId":"PPT_10b01c336ee5d00d","title":"Book 2 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 48","duration":69.17,"cues":[{"start":0,"end":1.56,"text":"Unit six,","coverage":1},{"start":2,"end":3.24,"text":"six .one","coverage":1},{"start":4.78,"end":8.46,"text":"one 48 %","coverage":1},{"start":11.8,"end":14.86,"text":"two one half","coverage":1},{"start":16.9,"end":18.18,"text":"one half","coverage":1},{"start":20.6,"end":22,"text":"three","coverage":1},{"start":22.68,"end":23.86,"text":"one fifth","coverage":1},{"start":26.08,"end":27.36,"text":"one fifth","coverage":1},{"start":30,"end":31.26,"text":"four","coverage":1},{"start":31.96,"end":33.96,"text":"31 .five","coverage":1},{"start":36.74,"end":39.92,"text":"five 103","coverage":1},{"start":47.6,"end":49,"text":"six","coverage":1},{"start":55.84,"end":57.24,"text":"seven","coverage":1},{"start":63.46,"end":67.24,"text":"eight zero .01","coverage":1}],"file":"b10d98cc5ae3be75c819.js","track":0,"media":"../assets/media/10b01c336ee5d00db87c0179556888bf72d8b76d6ab9913a27ed2e277576ff12.mp3"}],"../assets/media/f51ce3559a84e154b685e75b49f60f6078c7d11187149d232635f88a03adba3b.mp3":[{"id":"PPT_f51ce3559a84e154","audioId":"PPT_f51ce3559a84e154","title":"Book 2 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 56","duration":56.48,"cues":[{"start":0,"end":2.3,"text":"six .two","coverage":1},{"start":3.34,"end":3.68,"text":"Hello","coverage":1},{"start":3.68,"end":6.18,"text":"Hi, Professor Gould.","coverage":1},{"start":6.7,"end":7.8,"text":"This is Alika.","coverage":1},{"start":8.54,"end":11.04,"text":"Could I make an appointment to see you?","coverage":1},{"start":11.32,"end":14.52,"text":"I wanted to talk about my research project.","coverage":1},{"start":14.84,"end":16.36,"text":"I'm not done yet.","coverage":1},{"start":17.18,"end":21.9,"text":"Also, I'm not sure what I should write about for the business solution.","coverage":1},{"start":22.76,"end":23.78,"text":"Yes, of course.","coverage":1},{"start":24.42,"end":26.36,"text":"Can you tell me what you were able to finish?","coverage":1},{"start":27.28,"end":29.74,"text":"Well, I chose a problem.","coverage":1},{"start":30.44,"end":33.16,"text":"Then I found and read lots of articles.","coverage":1},{"start":33.66,"end":37,"text":"I have notes on information from my research.","coverage":1},{"start":37.54,"end":40.16,"text":"I met with my group for topic discussions,","coverage":1},{"start":40.68,"end":40.7,"text":"too.","coverage":1},{"start":41.58,"end":42.4,"text":"I see.","coverage":1},{"start":43.04,"end":44.56,"text":"Let's meet tomorrow then.","coverage":1},{"start":45.24,"end":46.9,"text":"Please bring your research notes.","coverage":1},{"start":47.54,"end":51.14,"text":"Let's discuss some causes and effects of the problem you researched.","coverage":1},{"start":52.02,"end":53.94,"text":"Can you meet at ten a .m.,","coverage":1},{"start":53.94,"end":54.56,"text":"Student Union?","coverage":1}],"file":"d40d4c40f7c435582371.js","track":0,"media":"../assets/media/f51ce3559a84e154b685e75b49f60f6078c7d11187149d232635f88a03adba3b.mp3"}],"../assets/media/bd0a1d9c4a09802bcdc5960cfed17349adecb6e638161613131f7d617b9a3094.mp3":[{"id":"PPT_bd0a1d9c4a09802b","audioId":"PPT_bd0a1d9c4a09802b","title":"Book 2 · Unit 6 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 109","duration":334.52,"cues":[{"start":0,"end":2,"text":"six .five","coverage":1},{"start":2.86,"end":3.26,"text":"Hi","coverage":1},{"start":3.26,"end":4.2,"text":"Sam,","coverage":1},{"start":4.7,"end":6,"text":"good to see you again.","coverage":1},{"start":6.26,"end":6.33,"text":"Hello","coverage":1},{"start":6.33,"end":7.1,"text":"Joe.","coverage":1},{"start":8.04,"end":8.3,"text":"So,","coverage":1},{"start":8.94,"end":13.26,"text":"last time we met we talked about your business goals.","coverage":1},{"start":13.92,"end":14.9,"text":"Was it useful?","coverage":1},{"start":15.58,"end":16.36,"text":"Useful?","coverage":1},{"start":16.78,"end":17.98,"text":"Yeah, it was.","coverage":1},{"start":18.72,"end":20.52,"text":"You really made me think.","coverage":1},{"start":21.18,"end":25.12,"text":"But now I have a lot of stress about losing money.","coverage":1},{"start":25.82,"end":25.98,"text":"Oh","coverage":1},{"start":25.98,"end":26.46,"text":"yes?","coverage":1},{"start":27.04,"end":29.28,"text":"What is making you stressed about that?","coverage":1},{"start":29.28,"end":34.26,"text":"Well, I realised how many weaknesses a business can have.","coverage":1},{"start":34.92,"end":38.76,"text":"One careless mistake and I could lose a lot of money.","coverage":1},{"start":39.62,"end":40.08,"text":"Exactly.","coverage":1},{"start":41.06,"end":44.62,"text":"But there are things you think will cause you to lose money?","coverage":1},{"start":45.38,"end":49.6,"text":"Well, when we looked at the company's strengths and weaknesses,","coverage":1},{"start":50.26,"end":60.6,"text":"we talked about the quality and happiness of my workers, the costs of running the business and reaching new customers to help grow the business.","coverage":1},{"start":61.52,"end":65.5,"text":"Each of these areas could be a way to help make money,","coverage":1},{"start":65.98,"end":69.94,"text":"or a way to lose money if you don't have a good plan.","coverage":1},{"start":70.7,"end":71.12,"text":"Wow,","coverage":1},{"start":71.52,"end":72.34,"text":"that's great.","coverage":1},{"start":72.94,"end":75.38,"text":"Those are all important to think about.","coverage":1},{"start":76.28,"end":77.8,"text":"Is there anything else?","coverage":1},{"start":78.44,"end":80.46,"text":"And what else was there?","coverage":1},{"start":80.76,"end":81.98,"text":"Oh, of course,","coverage":1},{"start":82.68,"end":83.2,"text":"customers.","coverage":1},{"start":83.2,"end":84.34,"text":"Well,","coverage":1},{"start":84.68,"end":87.22,"text":"that gives us plenty to talk about today.","coverage":1},{"start":88.1,"end":88.58,"text":"So,","coverage":1},{"start":89.08,"end":92.74,"text":"let's think about what you can do for your employees.","coverage":1},{"start":94.3,"end":99.58,"text":"You said that your workers were unhappy and not working hard enough.","coverage":1},{"start":100.8,"end":107.04,"text":"Keeping your employees happy will make them more likely to work hard for the business.","coverage":1},{"start":107.04,"end":113.78,"text":"Try organising some social events once a month during work hours.","coverage":1},{"start":114.4,"end":116.46,"text":"That could be a good first step.","coverage":1},{"start":117.8,"end":118.26,"text":"Also,","coverage":1},{"start":118.9,"end":122.08,"text":"maybe you should paint the walls a brighter colour.","coverage":1},{"start":122.9,"end":128,"text":"The office is really dark and people feel like they're in a cave.","coverage":1},{"start":128,"end":132.5,"text":"Brighter colours can help make people happier,","coverage":1},{"start":133.7,"end":137.34,"text":"and happier employees will also work harder.","coverage":1},{"start":137.78,"end":138.88,"text":"Oh, okay.","coverage":1},{"start":139.4,"end":140.92,"text":"Well, that's good to know.","coverage":1},{"start":141.94,"end":144.28,"text":"You also have to cut costs.","coverage":1},{"start":145.14,"end":149.5,"text":"You spend far too much money on electricity every month.","coverage":1},{"start":149.5,"end":154.98,"text":"Turn off the lights and computers at the end of the workday.","coverage":1},{"start":156.32,"end":162.74,"text":"You should also find some cheaper parts for your products, which are still well made.","coverage":1},{"start":163.76,"end":165.12,"text":"It's a tough job,","coverage":1},{"start":165.46,"end":167.56,"text":"but I can help you find them.","coverage":1},{"start":167.94,"end":168.54,"text":"I see.","coverage":1},{"start":168.9,"end":170.2,"text":"That would be great.","coverage":1},{"start":170.64,"end":174.4,"text":"If you spend less money, you can make a better profit.","coverage":1},{"start":174.4,"end":183.8,"text":"You have some excellent adverts, but you mentioned that you are having trouble reaching new customers,","coverage":1},{"start":184.84,"end":190.24,"text":"and growing your number of customers is really important for a successful business.","coverage":1},{"start":191.26,"end":193.24,"text":"So, if I were you,","coverage":1},{"start":193.62,"end":198.08,"text":"I would try adding online sales to get more customers.","coverage":1},{"start":198.08,"end":200.66,"text":"Yeah, I like that idea.","coverage":1},{"start":201.4,"end":206.1,"text":"I have a website already, but it looks pretty old and messy.","coverage":1},{"start":206.92,"end":209.2,"text":"But there are things we can work on.","coverage":1},{"start":210.08,"end":212.08,"text":"If you want to sell online,","coverage":1},{"start":212.74,"end":217.64,"text":"you should start by making sure that the website doesn't look messy.","coverage":1},{"start":218.72,"end":222,"text":"If you don't have the skills to make it look neat,","coverage":1},{"start":222.68,"end":225.08,"text":"hire a professional web designer.","coverage":1},{"start":225.08,"end":227.46,"text":"You want a neat,","coverage":1},{"start":227.88,"end":228.76,"text":"clean website.","coverage":1},{"start":229.56,"end":232.44,"text":"It isn't something you want to be careless with.","coverage":1},{"start":232.78,"end":233.36,"text":"I see.","coverage":1},{"start":234.22,"end":238.28,"text":"Well, I would like to have a lot of black on the website.","coverage":1},{"start":239.02,"end":243.18,"text":"I think that colour is professional and serious looking.","coverage":1},{"start":244.1,"end":245.22,"text":"I understand,","coverage":1},{"start":245.96,"end":249.78,"text":"but I think if you want to make the website attractive,","coverage":1},{"start":250.14,"end":251.46,"text":"it needs more colour.","coverage":1},{"start":251.46,"end":261.52,"text":"More colour could help the design pop out a bit more and prevent customers from leaving the website before buying anything.","coverage":1},{"start":262.1,"end":262.5,"text":"Aha,","coverage":1},{"start":262.86,"end":264.2,"text":"that's a good idea.","coverage":1},{"start":264.96,"end":267.26,"text":"I actually like blue too.","coverage":1},{"start":267.78,"end":271.68,"text":"I think someone else told me about colours people prefer,","coverage":1},{"start":272.26,"end":273.32,"text":"but I forgot.","coverage":1},{"start":273.32,"end":278.76,"text":"Yes, it's easy to forget to think about something as simple as colour.","coverage":1},{"start":280.04,"end":285.8,"text":"The web designer you hire might have some good ideas about which colours to use.","coverage":1},{"start":286.98,"end":287.38,"text":"So,","coverage":1},{"start":288,"end":289.42,"text":"for our next meeting,","coverage":1},{"start":290.2,"end":294.14,"text":"you should create your website design and bring a plan.","coverage":1},{"start":294.86,"end":299.2,"text":"You could think about how it looks as well as what it says.","coverage":1},{"start":300.5,"end":302.86,"text":"You don't want it to look...","coverage":1},{"start":302.86,"end":303.3,"text":"well,","coverage":1},{"start":303.88,"end":308.88,"text":"you would want to be sure it looks well organised and the best it can be.","coverage":1},{"start":309.74,"end":312.8,"text":"It should also be really easy to use.","coverage":1},{"start":314.1,"end":318.8,"text":"Next time we'll go over your design and see how to make it better.","coverage":1},{"start":319.78,"end":328.04,"text":"We will also think about hiring a good web designer to make your website look great and be easy to use.","coverage":1},{"start":328.7,"end":329.56,"text":"Okay, great.","coverage":1},{"start":330.08,"end":332.58,"text":"I'll do that and bring it in next week.","coverage":1}],"file":"ee972a2ae24e6d5c9a27.js","track":0,"media":"../assets/media/bd0a1d9c4a09802bcdc5960cfed17349adecb6e638161613131f7d617b9a3094.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 After you leave school or university and get a job, do you have to study more? Why / Why not?Possible answer: Yes. I may need to learn how to do a new job or use new technology.","slide":4,"shape":"16","bookPage":"126"},{"text":"2 What are some ways that a job might change over time?Possible answer: The technology, tasks or skills needed for a job might change.","slide":4,"shape":"18","bookPage":"126"},{"text":"3 When you want to change jobs, what can you do so other companies will want you?Possible answer: I can develop the skills that the company needs and show examples of my work.","slide":5,"shape":"16","bookPage":"126"},{"text":"1 Why might workers need re-training?Possible answer: Workers may need to learn new skills when they change jobs or their workchanges.","slide":7,"shape":"26","bookPage":"126"},{"text":"2 What happens if your job doesn’t exist any more?Possible answer: You may need to find a different job and learn the skills it requires.","slide":7,"shape":"27","bookPage":"126"},{"text":"3 What type of work skills do you think the video mentions? Why?Possible answer: The video may mention technology skills and skills for greener industries.","slide":7,"shape":"28","bookPage":"126"},{"text":"1  Schools provide education for young people.","slide":15,"shape":"8","bookPage":"126"},{"text":"2  Practising a task can help you develop your abilities.","slide":15,"shape":"9","bookPage":"126"},{"text":"3  The travel industry includes many kinds of business.","slide":15,"shape":"10","bookPage":"126"},{"text":"4  A skill helps you do an activity well.","slide":15,"shape":"11","bookPage":"126"},{"text":"5  Workers can learn new abilities through re-training.","slide":15,"shape":"12","bookPage":"126"},{"text":"6  Some types of work may not exist in the future.","slide":15,"shape":"13","bookPage":"126"},{"text":"Upskilling is important because it helps you keep your job or get the job you really want.","slide":18,"shape":"10","bookPage":"126"},{"text":"1 Almost 50% of all workers think their job might not exist in five years.","slide":21,"shape":"5","bookPage":"127"},{"text":"2 Upskilling can be learning new skills.","slide":21,"shape":"17","bookPage":"127"},{"text":"3 You can upskill by re-training.","slide":22,"shape":"5","bookPage":"127"},{"text":"4 Upskilling makes workers happier in their work.","slide":22,"shape":"11","bookPage":"127"},{"text":"1 Learning more about a computer program that you used in the past is upskilling.False. Learning more about a computer program that you use now is upskilling.","slide":24,"shape":"7","bookPage":"127"},{"text":"2 New skills can include giving talks to companies or speaking another language.False. New skills can include giving talks to customers or speaking anotherlanguage.","slide":24,"shape":"17","bookPage":"127"},{"text":"3 Upskilling isn’t important for people who work in hotels or on farms.False. Upskilling is important for people who work in hotels or on farms.","slide":24,"shape":"5","bookPage":"127"},{"text":"4 People who keep learning at work have better jobs than people who do not.True, according to the video. Continuing to learn can help people get better jobs.","slide":25,"shape":"10","bookPage":"127"},{"text":"Why do you think upskilling makes people happier in their work?Possible answer: People may get a more interesting job, earn more and feel more useful or confident at work.","slide":27,"shape":"10","bookPage":"127"},{"text":"1 What was something important that you learned from this video?Possible answer: I learned that I need to keep developing my skills after I leave school.","slide":29,"shape":"16","bookPage":"127"},{"text":"2 Why do you think climate change makes people need to upskill?Possible answer: Industries may use greener technology, so workers need to learn how to use it.","slide":29,"shape":"18","bookPage":"127"},{"text":"3 Should companies help workers to upskill or should workers learn on their own? Why?Possible answer: Companies should help because better skills can improve the business. Workerscan also choose skills for their own future.","slide":30,"shape":"16","bookPage":"127"},{"text":"project / earnA project is planned work with a purpose. Earn means get money from working.","slide":42,"shape":"15","bookPage":"128"},{"text":"profit / colleaguesProfit is money left after costs. Colleagues are people who work with you.","slide":42,"shape":"17","bookPage":"128"},{"text":"spend time / waste time / breaksSpend time means use time. Waste time means use it badly. Breaks are shortpauses in work.","slide":42,"shape":"6","bookPage":"128"},{"text":"1 What would you prefer: to earn more money or to have more free time?Possible answer: I would prefer more free time because I want to spend time with my family.","slide":44,"shape":"16","bookPage":"128"},{"text":"2 This company makes a lot of money and we share the profit with the workers. When do you want to get that extra money: once a month, once a year or when you leave your job? Why?Possible answer: I would like to receive my share every month so I do not have to wait for it.","slide":44,"shape":"18","bookPage":"128"},{"text":"3 What type of colleagues do you enjoy working with? Why?Possible answer: I enjoy working with friendly, hard-working colleagues who share ideas.","slide":45,"shape":"16","bookPage":"128"},{"text":"4 What type of projects do you prefer to spend time working on? Why? (For example, do you prefer team projects or individual ones?)Possible answer: I prefer team projects because I learn from other people.","slide":45,"shape":"18","bookPage":"128"},{"text":"5 What work activities do you think waste your time during the day? (For example, reading emails, long meetings or travelling to work.) What can the company do to improve this?Possible answer: Long meetings waste my time. The company could make them shorter and givethem a clear purpose.","slide":46,"shape":"16","bookPage":"128"},{"text":"6 How much time do you want for breaks in the morning, at lunchtime and in the afternoon?Possible answer: I would like a short morning break, an hour for lunch and a short afternoon break.","slide":46,"shape":"18","bookPage":"128"},{"text":"1 48%forty-eight percent","slide":49,"shape":"7","bookPage":"129"},{"text":"2 ½a half / one half","slide":49,"shape":"18","bookPage":"129"},{"text":"3 ⅕a fifth / one fifth","slide":49,"shape":"20","bookPage":"129"},{"text":"4 31.5thirty-one point five","slide":50,"shape":"7","bookPage":"129"},{"text":"5 103one hundred and three / one oh three","slide":50,"shape":"18","bookPage":"129"},{"text":"6 1,540one thousand, five hundred and forty","slide":50,"shape":"20","bookPage":"129"},{"text":"7 6,001six thousand and one","slide":51,"shape":"14","bookPage":"129"},{"text":"8 0.01nought point nought one","slide":51,"shape":"16","bookPage":"129"},{"text":"1 57%: fifty-seven percent","slide":53,"shape":"16","bookPage":"129"},{"text":"2 ⅓: one third / a third","slide":53,"shape":"18","bookPage":"129"},{"text":"3 16.75: sixteen point seven five","slide":54,"shape":"10","bookPage":"129"},{"text":"4 2,647: two thousand, six hundred and forty-seven","slide":54,"shape":"12","bookPage":"129"},{"text":"Why did Alika call her professor?Alika wanted to make an appointment to get advice about her research project.","slide":56,"shape":"11","bookPage":"129"},{"text":"Internet and online use: almost (1) half of all workers wasted time surfinginternet or writing personal (2) emails.","slide":61,"shape":"7","bookPage":"130"},{"text":"(3) 31.5 % spent time talking to colleagues.","slide":61,"shape":"8","bookPage":"130"},{"text":"Under (4) half that amount took longer coffee and lunch breaks.","slide":61,"shape":"9","bookPage":"130"},{"text":"½ not happy in their (5) jobs.","slide":62,"shape":"7","bookPage":"130"},{"text":"⅓ thought they didn’t (6) earn a good enough salary.","slide":62,"shape":"8","bookPage":"130"},{"text":"Not enough money for holidays and nice (7) clothes.","slide":62,"shape":"9","bookPage":"130"},{"text":"(8) 19 % have to work too many hours.","slide":62,"shape":"10","bookPage":"130"},{"text":"Workers don’t work hard; productivity goes down, so company makes less money than itwanted to and can’t pay workers higher (9) salaries.","slide":63,"shape":"7","bookPage":"130"},{"text":"1 Alika finished her research project.False. Alika has not finished her research project.","slide":65,"shape":"7","bookPage":"130"},{"text":"2 She read more than 100 different reports.True. She read about 103 different reports.","slide":65,"shape":"18","bookPage":"130"},{"text":"3 Alika studied why people work.False. Alika studied how people work.","slide":65,"shape":"20","bookPage":"130"},{"text":"4 Alika wanted to know why people didn’t work hard at their jobs.True. She wanted to know why people did not work hard at their jobs.","slide":66,"shape":"14","bookPage":"130"},{"text":"5 Alika found some information that wasn’t interesting.False. Alika says she found a lot of interesting information.","slide":66,"shape":"16","bookPage":"130"},{"text":"1  Internet and writing emails: 48 %","slide":68,"shape":"8","bookPage":"131"},{"text":"2  Longer coffee and lunch breaks: 15 %","slide":68,"shape":"9","bookPage":"131"},{"text":"48% / almost halfabout half / approximately half / almost fifty percent","slide":73,"shape":"15","bookPage":"131"},{"text":"31.5%about a third / about one third","slide":73,"shape":"17","bookPage":"131"},{"text":"15% / a little under half that amounta little under half of 31.5%","slide":73,"shape":"6","bookPage":"131"},{"text":"5%five percent","slide":74,"shape":"15","bookPage":"131"},{"text":"approximately halfabout 50% / about one half","slide":74,"shape":"17","bookPage":"131"},{"text":"33.5% / about a thirdabout one third","slide":74,"shape":"6","bookPage":"131"},{"text":"5%five percent / one twentieth","slide":75,"shape":"9","bookPage":"131"},{"text":"about 19%almost 20%","slide":75,"shape":"11","bookPage":"131"},{"text":"1. Alika ran out of time.","slide":78,"shape":"5","bookPage":null},{"text":"11. What is Alika discussing with Professor Gould?\nA. Her research project\nB. A holiday booking\nC. A new job offer","slide":78,"shape":"8","bookPage":null},{"text":"stress / goalsStress means worry caused by difficulties. Goals are things you want to achieve.","slide":92,"shape":"15","bookPage":"137"},{"text":"careless / messyCareless means not paying enough attention. Messy means untidy or badlyorganized.","slide":92,"shape":"17","bookPage":"137"},{"text":"customers / skills / hireCustomers buy from a business. Skills help you do a task well. Hire means givesomebody a job.","slide":94,"shape":"9","bookPage":"137"},{"text":"strengths / weaknessesStrengths are good qualities or abilities. Weaknesses are areas where you are notstrong.","slide":94,"shape":"11","bookPage":"137"},{"text":"1 Look at the photo. Which person is the business advisor? How do you know?Possible answer: The man on the right might be the adviser because he seems to be listening to the other person’s problems.","slide":96,"shape":"7","bookPage":"137"},{"text":"2 Why would a business owner need advice from an advisor?Possible answer: An owner may need advice when a business is new or has problems.","slide":96,"shape":"17","bookPage":"137"},{"text":"3 What skills do you think you need to be a business advisor? Why?Possible answer: An adviser needs to listen carefully and understand business problems.","slide":96,"shape":"19","bookPage":"137"},{"text":"4 Do you think you would be a good business advisor? Why / Why not?Possible answer: I could be a good adviser because I listen carefully, but I would need morebusiness experience.","slide":97,"shape":"10","bookPage":"137"},{"text":"1 What are your goals for the future?Possible answer: A goal of mine is to lead a team and help it do good work.","slide":100,"shape":"7","bookPage":"138"},{"text":"2 What do you do if you are stressed at work?Possible answer: If I am stressed, I take a short break so I do not make a careless mistake.","slide":100,"shape":"17","bookPage":"138"},{"text":"3 What are your strengths?Possible answer: One of my strengths is that I work hard and listen to colleagues.","slide":100,"shape":"19","bookPage":"138"},{"text":"4 What computer or language skills do you have?Possible answer: I can use office software and communicate in English and my own language.","slide":101,"shape":"13","bookPage":"138"},{"text":"5 Why should my company hire you?Possible answer: I have the skills and experience you want. I can help the company solve problems and grow.","slide":101,"shape":"15","bookPage":"138"},{"text":"Business goals: Ways to make money, not (1) lose money!","slide":107,"shape":"17","bookPage":"138"},{"text":"Quality and (2) happiness of workers:","slide":107,"shape":"19","bookPage":"138"},{"text":"(3) Costs of running business:","slide":108,"shape":"11","bookPage":"138"},{"text":"Reach new (4) customers:","slide":108,"shape":"13","bookPage":"138"},{"text":"Paint walls a (5) brighter colour.","slide":114,"shape":"10","bookPage":"138"},{"text":"Employees may work (6) harder.","slide":114,"shape":"11","bookPage":"138"},{"text":"Right now: spending (7) too much money on electricity.","slide":115,"shape":"8","bookPage":"138"},{"text":"Find (8) cheaper parts (consultant can help).","slide":115,"shape":"10","bookPage":"138"},{"text":"Website looks pretty old and (9) messy.","slide":116,"shape":"10","bookPage":"138"},{"text":"Don’t want to be (10) careless with website.","slide":116,"shape":"12","bookPage":"138"},{"text":"Website should look (11) well organized — best it can be.","slide":117,"shape":"8","bookPage":"138"},{"text":"We want to tell you our Top Five Business Tips.","slide":125,"shape":"13","bookPage":"139"},{"text":"1 Make employees happier with a pleasant office.","slide":125,"shape":"14","bookPage":"139"},{"text":"2 Organize social events so colleagues can get to know each other.","slide":125,"shape":"15","bookPage":"139"},{"text":"3 Cut electricity costs. Turn off lights at the end of the day.","slide":125,"shape":"16","bookPage":"139"},{"text":"4 Buy cheaper parts that are still well made.","slide":125,"shape":"6","bookPage":"139"},{"text":"5 Improve the website so customers can find and buy products easily.","slide":125,"shape":"7","bookPage":"139"},{"text":"1 What did people do the least?Workers spent the least time on the phone.","slide":130,"shape":"7","bookPage":"132"},{"text":"2 What did people do more than spending time in meetings?Answer: People spent more time taking breaks or working at a desk than in meetings.","slide":130,"shape":"17","bookPage":"132"},{"text":"3 What did people do the most?Answer: People spent the most time working at a desk.","slide":130,"shape":"5","bookPage":"132"},{"text":"4 What did people do less than taking breaks?Answer: People spent less time on the phone or in meetings than taking breaks.","slide":131,"shape":"10","bookPage":"132"},{"text":"1 Which jobs are more popular than others? Why?","slide":140,"shape":"9","bookPage":"134"},{"text":"2 Do you think that your time at work is more important than your time outside of work? Why?","slide":140,"shape":"16","bookPage":"134"},{"text":"3 Which is worse: a job with low pay or a job with a lot of stress? Why?","slide":140,"shape":"5","bookPage":"134"},{"text":"4 Which do you think is better: working in an office or working from home? Why?","slide":140,"shape":"7","bookPage":"134"},{"text":"5 What is the most important reason to work? Why?","slide":141,"shape":"5","bookPage":"134"},{"text":"6 Which company do you think has the happiest workers?","slide":141,"shape":"16","bookPage":"134"},{"text":"1 Which jobs are more popular than others? Why?Possible answer: Some people prefer office jobs because the hours are more regular than in other jobs.","slide":145,"shape":"7","bookPage":"134"},{"text":"2 Do you think that your time at work is more important than your time outside of work? Why?Possible answer: My time outside work is as important as my time at work.","slide":145,"shape":"17","bookPage":"134"},{"text":"3 Which is worse: a job with low pay or a job with a lot of stress? Why?Possible answer: A very stressful job is worse for me because it is harder to relax after work.","slide":145,"shape":"19","bookPage":"134"},{"text":"4 Which do you think is better: working in an office or working from home? Why?Possible answer: Working from home is better for me because I spend less time travelling.","slide":146,"shape":"7","bookPage":"134"},{"text":"5 What is the most important reason to work? Why?Possible answer: For me, the most important reason is to earn enough money for my family.","slide":146,"shape":"17","bookPage":"134"},{"text":"6 Which company do you think has the happiest workers?Possible answer: I think a company that listens to its workers may have the happiest employees.","slide":146,"shape":"19","bookPage":"134"},{"text":"1 Friendly colleagues are the least important reason in this chart.","slide":149,"shape":"17","bookPage":"134"},{"text":"2 Great benefits are less important than interesting work.","slide":149,"shape":"19","bookPage":"134"},{"text":"3 Interesting work is more important than friendly colleagues.","slide":149,"shape":"6","bookPage":"134"},{"text":"4 Friendly colleagues are less important than great benefits.","slide":149,"shape":"8","bookPage":"134"},{"text":"5 Important work is less important than good pay.","slide":150,"shape":"15","bookPage":"134"},{"text":"A: I wrote, ‘Friendly colleagues are less important than important work.’ How about you?","slide":153,"shape":"12","bookPage":"134"},{"text":"B: I had the same idea, but I wrote, ‘Friendly colleagues are the least important toemployees in this chart.’","slide":153,"shape":"13","bookPage":"134"},{"text":"C: I wrote, ‘Friendly colleagues aren’t as important as important work.’","slide":153,"shape":"14","bookPage":"134"},{"text":"1 Which of the reasons for happiness at work from the chart are the same as yours?Possible answer: Interesting work and friendly colleagues are important for me too.","slide":155,"shape":"16","bookPage":"135"},{"text":"2 Which reasons in the chart are the most important for you? Why?Possible answer: Friendly colleagues are the most important for me because I spend a lot of timewith them.","slide":155,"shape":"18","bookPage":"135"},{"text":"3 What other reasons for happiness at work do you have?Possible answer: Learning new skills would make me happy because it could help me find a betterjob.","slide":156,"shape":"16","bookPage":"135"},{"text":"1 You wrote a lot of information down in my notebook.","slide":168,"shape":"7","bookPage":"135"},{"text":"2 I haven’t finished yet. I ran out of time.","slide":168,"shape":"16","bookPage":"135"},{"text":"3 I wrote down some notes during the lecture.","slide":168,"shape":"5","bookPage":"135"},{"text":"4 Sandra took over from Mark as the project manager.","slide":169,"shape":"5","bookPage":"135"},{"text":"5 Amal found out a lot of information about the way people work.","slide":169,"shape":"16","bookPage":"135"},{"text":"6 Mona looked at how people use their time at work.","slide":170,"shape":"5","bookPage":"135"},{"text":"7 Faisal had just enough money to get by each month.","slide":170,"shape":"10","bookPage":"135"},{"text":"1 My company often runs out of products to sell.","slide":172,"shape":"16","bookPage":"136"},{"text":"2 Some workers do not turn off the machines at the end of the day.","slide":172,"shape":"18","bookPage":"136"},{"text":"3 If a company has too few customers, it may not have enough money to get by.","slide":172,"shape":"6","bookPage":"136"},{"text":"4 The company does not bring in enough money to pay its workers.","slide":172,"shape":"8","bookPage":"136"},{"text":"5 We are looking at ways to reduce costs.","slide":173,"shape":"16","bookPage":"136"},{"text":"6 Shop workers should watch out for people who might steal things.","slide":173,"shape":"18","bookPage":"136"},{"text":"1 Correct: How do you find information out about a company’s products?","slide":175,"shape":"9","bookPage":"136"},{"text":"2 Correct: Do you think it’s easy to take a project over in the middle of work? Why /Why not?","slide":175,"shape":"19","bookPage":"136"},{"text":"3 How can people watch out for problems at work?","slide":175,"shape":"5","bookPage":"136"},{"text":"4 What happens if a business runs out of money?","slide":175,"shape":"7","bookPage":"136"},{"text":"5 Do you look at how to improve if you make a mistake? Why / Why not?","slide":176,"shape":"5","bookPage":"136"},{"text":"6 Correct: What are some ways that a business could bring more money in?","slide":176,"shape":"19","bookPage":"136"},{"text":"How do you find information out about a company’s products?Possible answer: I look at the company’s website or ask friends about the products.","slide":178,"shape":"16","bookPage":"136"},{"text":"Do you think it’s easy to take a project over in the middle of work? Why /Why not?Possible answer: It can be difficult because you need to understand work that someone else started.","slide":178,"shape":"18","bookPage":"136"},{"text":"How can people watch out for problems at work?Possible answer: People can watch out for problems by checking their work carefully.","slide":179,"shape":"7","bookPage":"136"},{"text":"What happens if a business runs out of money?Possible answer: If a business runs out of money, it may close and workers may lose their jobs.","slide":179,"shape":"17","bookPage":"136"},{"text":"Do you look at how to improve if you make a mistake? Why / Why not?Possible answer: Yes. I look at what went wrong so I can avoid making the mistake again.","slide":179,"shape":"19","bookPage":"136"},{"text":"What are some ways that a business could bring more money in?Possible answer: A business could bring in more money by reaching new customers online.","slide":180,"shape":"16","bookPage":"136"},{"text":"This company has fewer employees than ours.","slide":184,"shape":"6","bookPage":null},{"text":"We need to find out the opening times.","slide":184,"shape":"9","bookPage":null},{"text":"I found a useful place to buy notebooks. There is a new shop beside the station. That shop sells notebooks for two pounds each. This is cheaper than the price at my old shop.","slide":185,"shape":"6","bookPage":null},{"text":"My cousin has started something new. She has set up a small bakery. The bakery sells three kinds of bread. The brown bread is the most popular of the three.","slide":186,"shape":"6","bookPage":null},{"text":"A man is arranging jars on a shop shelf. He is looking carefully at one of the jars.","slide":187,"shape":"7","bookPage":null},{"text":"I could write down how many jars are on each shelf. This could help the shop avoid running out of an item.","slide":188,"shape":"7","bookPage":null},{"text":"1. Before the meeting, Alika had written down a lot of information.","slide":193,"shape":"5","bookPage":null},{"text":"11. Which description of Alika’s progress is accurate?\nA. She had finished before doing any reading.\nB. She had not started the work.\nC. She had done substantial reading but had not finished.","slide":193,"shape":"8","bookPage":null},{"text":"1. Professor Gould thinks Alika has done very little reading for her project.\nAnswer: FALSE","slide":196,"shape":"5","bookPage":null},{"text":"11. The workers who complained about their pay had enough money for holidays and nice clothes.\nAnswer: FALSE","slide":196,"shape":"8","bookPage":null},{"text":"Our new printer uses less paper than the old one.","slide":205,"shape":"6","bookPage":null},{"text":"We should look up the delivery price.","slide":205,"shape":"9","bookPage":null},{"text":"I compared the delivery services this morning. The first service arrives in two days. The second needs twice as long. I chose the first because it is faster.","slide":206,"shape":"6","bookPage":null},{"text":"Our old machine was becoming expensive to use. It used a lot of electricity. That high use increased our bills. The replacement uses less electricity.","slide":207,"shape":"6","bookPage":null},{"text":"Two colleagues are discussing a plan. They can find out which task is most important. Their project may become better organized.","slide":208,"shape":"7","bookPage":null},{"text":"The colleagues can write down clear goals. Then they can spend time on each task. This may reduce stress.","slide":209,"shape":"7","bookPage":null},{"text":"Problems\nPossible solutions\nPossible results\nThe employees are unhappy and don’t work hard.\nc Organize social events and paint the office walls brighter colours.\nEmployees will be happier and work harder.\nThe company spends too much money on electricity and parts for the products it makes.\na Turn off the lights and computers at the end of the day; find cheaper parts for the products you make.\nThe business can save money and make more of a profit.","slide":223,"shape":"14","bookPage":"140"},{"text":"Problems\nPossible solutions\nPossible results\nThe business isn’t getting new customers.\nb Add online sales.\nThe business can gain online sales and new customers.\nThe business has an old, messy website.\nd Hire a professional web designer to create a well-organized website that is easier to use.\nThe website can become more attractive and easier to use, helping the business gain online customers.","slide":224,"shape":"14","bookPage":"140"},{"text":"Problem\nPossible solution\nPossible result\nOnly open three days a week\nOpen for more hours or days.\nCustomers have more time to visit and buy.\nThe owner does not use social media\nUse social media to show the art.\nMore potential customers may find the shop.","slide":233,"shape":"16","bookPage":"141"},{"text":"Problem\nPossible solution\nPossible result\nOnly one online payment method\nOffer more ways to pay.\nMore customers may be able to complete a purchase.\nPrices are too high for some visitors\nOffer more popular art at lower prices.\nCustomers may buy more items.","slide":234,"shape":"17","bookPage":"141"},{"text":"Problem\nPossible solution\nPossible result\nThe website cannot handle many orders\nHire a technical company to repair and improve it.\nThe website can work reliably and accept more orders.\nCustomers order from other companies\nOffer a suitable discount or a small gift to returning customers.\nCustomers may return and buy again.","slide":235,"shape":"17","bookPage":"141"},{"text":"Problem\nPossible solution\nPossible result\nThe business is losing money\nFix ordering problems and track whether sales improve.\nThe business may recover sales of its popular product.","slide":236,"shape":"17","bookPage":"141"},{"text":"Problem\nPossible solution\nPossible result\nOnly tea is available\nOffer food and other drinks that customers want.\nCustomers may have more reasons to return.\nA popular restaurant attracts customers\nOffer products or a service the restaurant does not provide.\nThe tea shop may attract different customers.","slide":237,"shape":"17","bookPage":"141"},{"text":"Problem\nPossible solution\nPossible result\nCustomers do not return\nVisit successful tea shops and learn what customers like.\nThe owner may make the shop more appealing.","slide":238,"shape":"16","bookPage":"141"},{"text":"The shopIt is hard to know what the shop sells. It may sell fishing equipment or fish to eat. Italso looks untidy.","slide":241,"shape":"12","bookPage":"142"},{"text":"1 If I were you, I would paint the shop.","slide":243,"shape":"17","bookPage":"143"},{"text":"2 I think you should clean the shop more often.","slide":243,"shape":"19","bookPage":"143"},{"text":"3 If you want to do better, you should use the internet for advertising.","slide":243,"shape":"6","bookPage":"143"},{"text":"4 Be careful not to have unpleasant smells in the shop.","slide":243,"shape":"8","bookPage":"143"},{"text":"5 You should try to make the shop’s name and signs clearer.","slide":244,"shape":"15","bookPage":"143"},{"text":"Advisor: I think you should try to improve your shop.","slide":246,"shape":"16","bookPage":"143"},{"text":"Advisor: If I were you, I would try to make the store signs easier to understand.","slide":246,"shape":"18","bookPage":"143"},{"text":"Advisor: Why don’t you hire a sign designer?","slide":250,"shape":"10","bookPage":"143"},{"text":"Advisor: And if you want to bring in more customers, you should try to use social media.","slide":250,"shape":"12","bookPage":"143"},{"text":"My colleagues don’t help me on projects.Possible advice: You should spend time helping your colleagues. They may be more willing to help you too.","slide":254,"shape":"7","bookPage":"190"},{"text":"I want to do well at work, but I’m not sure how to improve.Possible advice: I think you should ask colleagues or your boss how you can improve.","slide":254,"shape":"18","bookPage":"190"},{"text":"I get too nervous talking in front of others.Possible advice: You should practise what you want to say with a friend or in front of a mirror.","slide":254,"shape":"20","bookPage":"190"},{"text":"Other people make a lot of mistakes and I have to fix things.Possible advice: You could help colleagues learn how to avoid the mistakes, so the same problems happen less often.","slide":255,"shape":"7","bookPage":"190"},{"text":"I’m good at working in teams, but it’s hard to have a boss.Possible advice: Try to understand which tasks are your responsibility and speak politely when you need clarification.","slide":255,"shape":"18","bookPage":"190"},{"text":"My company wants me to work long hours.Possible advice: You should discuss your hours with your manager and agree on realistic priorities.","slide":255,"shape":"20","bookPage":"190"},{"text":"A: I think a small business should make it easy for customers to find information online.","slide":257,"shape":"11","bookPage":"143"},{"text":"B: I agree. It should also choose opening hours that suit its customers.","slide":257,"shape":"12","bookPage":"143"},{"text":"C: Yes. And it should check costs regularly so it does not spend more than it earns.","slide":257,"shape":"13","bookPage":"143"},{"text":"1–2 CustomersFind out what customers need. Ask for feedback.","slide":259,"shape":"16","bookPage":"143"},{"text":"3–4 InformationKeep product information clear. Make the website easy to use.","slide":259,"shape":"18","bookPage":"143"},{"text":"5–6 AccessChoose convenient opening hours. Offer suitable ways to pay.","slide":259,"shape":"6","bookPage":"143"},{"text":"7–8 CostsCheck costs regularly. Avoid wasting electricity and materials.","slide":260,"shape":"13","bookPage":"143"},{"text":"9–10 WorkersHelp workers learn useful skills. Listen to their suggestions.","slide":260,"shape":"15","bookPage":"143"},{"text":"If I were you, I would offer more ways to pay. Customers who do not use credit cardscould then buy from you.","slide":269,"shape":"11","bookPage":"144"},{"text":"I think you should improve your website so people can find out about your products moreeasily.","slide":269,"shape":"12","bookPage":"144"},{"text":"You should offer some cheaper art. More customers might be able to buy it.","slide":269,"shape":"13","bookPage":"144"},{"text":"If you want to reach more people, you should use social media to show your products.","slide":269,"shape":"14","bookPage":"144"},{"text":"B: I think you should try to improve your shop.","slide":277,"shape":"15","bookPage":"144"},{"text":"A: Oh? What should I do?","slide":277,"shape":"16","bookPage":"144"},{"text":"B: If I were you, I would try opening your shop for more hours. Four or five days a weekwould be better. It would give more time to make sales.","slide":277,"shape":"17","bookPage":"144"},{"text":"A: I see. What else?","slide":278,"shape":"14","bookPage":"144"},{"text":"B: If you want more customers, you should try to use social media. That way, morepeople will find out about your business on your website.","slide":278,"shape":"15","bookPage":"144"},{"text":"A: OK. I’ll try to do that. Do you have any other advice?","slide":279,"shape":"13","bookPage":"144"},{"text":"B: One last thing. I see that you have popular artists, but your customers only buy cheapart pieces. I think the prices are too high. You should look at your prices and think aboutmaking them about 20% lower.","slide":279,"shape":"14","bookPage":"144"},{"text":"A: Thank you. I think that is all good advice.","slide":279,"shape":"15","bookPage":"144"},{"text":"If I were you, I would compare the prices.","slide":283,"shape":"6","bookPage":null},{"text":"Be careful not to spend all the money.","slide":283,"shape":"9","bookPage":null},{"text":"Customers need to know what they will pay. The stall has no prices on display. Without those prices, people keep asking the same question. I think the owner should add clear labels.","slide":284,"shape":"6","bookPage":null},{"text":"I would begin with the food left at closing time. The café throws away unsold sandwiches. Those leftovers suggest it prepares too many. The owner could make fewer and review the results.","slide":285,"shape":"6","bookPage":null},{"text":"I think they should write their possible goals on the board. They could then compare which one needs attention first. This would give both colleagues a clear view of the options. They could choose one goal to work on next.","slide":286,"shape":"7","bookPage":null},{"text":"If I were them, I would ask each person to explain one priority. They could write down the reasons beside the tasks. This might show where their ideas overlap. They could then agree on a practical first step.","slide":287,"shape":"7","bookPage":null}];
